// Passo 1: classe mãe — o que TODA mídia tem.
class Midia {
  constructor(titulo, ano) {
    this.titulo = titulo;
    this.ano = ano;
  }
  descricao() {
    return `Mídia: ${this.titulo} (${this.ano})`;
  }
}

// Passos 2 e 3: livro herda da mãe, acrescenta campos e substitui a descrição.
class Livro extends Midia {
  constructor(titulo, ano, autor, paginas) {
    super(titulo, ano); // chamada da mãe — detalhes na próxima aula
    this.autor = autor;
    this.paginas = paginas;
  }
  descricao() {
    return `Livro: ${this.titulo} (${this.ano}) — ${this.autor}, ${this.paginas} páginas`;
  }
}

// Passo 4: DVD, mesmo padrão.
class DVD extends Midia {
  constructor(titulo, ano, diretor, duracaoMin) {
    super(titulo, ano);
    this.diretor = diretor;
    this.duracaoMin = duracaoMin;
  }
  descricao() {
    return `DVD: ${this.titulo} (${this.ano}) — ${this.diretor}, ${this.duracaoMin} min`;
  }
}

// Passo 5: herança em ação — campos da mãe + descrição de cada um.
const livro = new Livro('O Cortiço', 1890, 'Aluísio Azevedo', 320);
const dvd = new DVD('Matrix', 1999, 'Lana Wachowski', 136);
console.log(livro instanceof Midia); // imprime: true  (livro É uma mídia)
console.log(livro.titulo);           // imprime: O Cortiço  (herdado)
console.log(livro.descricao());      // imprime: Livro: O Cortiço (1890) — ...
console.log(dvd.descricao());        // imprime: DVD: Matrix (1999) — ...
